/// What the currently connected core can actually do.
///
/// The UI gates navigation and affordances on these flags rather than probing
/// the server itself: capability detection is server- and build-dependent
/// (an Open WebUI version, a Hermes deployment, a macOS-only helper), and
/// duplicating that logic in the renderer is exactly the drift the workspace
/// rules exist to stop.
///
/// A flat struct is safe here because `kConduitProtocolVersion` demands strict
/// equality — the daemon and the UI are always the same build, so there is no
/// "older peer sees an unknown flag" case to design around.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, Default)]
#[serde(rename_all = "camelCase")]
pub struct Capabilities {
    /// Some workspace section can be managed: the Workspace section. Which
    /// ones are the `workspace*` flags below.
    #[serde(default)]
    pub workspace: bool,
    #[serde(default)]
    pub notes: bool,
    #[serde(default)]
    pub channels: bool,
    /// Hermes's sessions: Hermes is on (or the only backend).
    #[serde(default)]
    pub hermes: bool,
    #[serde(default)]
    pub terminal: bool,
    #[serde(default)]
    pub calendar: bool,
    /// Scheduled tasks.
    #[serde(default)]
    pub automations: bool,
    /// Hermes is the only backend: its sessions take the chats' place, and
    /// Open WebUI's own sections are hidden.
    #[serde(default)]
    pub hermes_only: bool,
    #[serde(default)]
    pub workspace_models: bool,
    #[serde(default)]
    pub workspace_knowledge: bool,
    #[serde(default)]
    pub workspace_prompts: bool,
    #[serde(default)]
    pub workspace_tools: bool,
    #[serde(default)]
    pub workspace_skills: bool,
    /// Folders can be listed and made.
    #[serde(default)]
    pub folders: bool,
    /// Webhook destinations for notifications.
    #[serde(default)]
    pub webhooks: bool,
    #[serde(default)]
    pub memories: bool,
    #[serde(default)]
    pub code_interpreter: bool,
    #[serde(default)]
    pub image_generation: bool,
    #[serde(default)]
    pub web_search: bool,
    #[serde(default)]
    pub direct_connections: bool,
    #[serde(default)]
    pub mcp: bool,
    #[serde(default)]
    pub server_stt: bool,
    #[serde(default)]
    pub on_device_stt: bool,
    #[serde(default)]
    pub server_tts: bool,
    #[serde(default)]
    pub device_tts: bool,
    #[serde(default)]
    pub apple_on_device_models: bool,
    #[serde(default)]
    pub apple_pcc: bool,
    #[serde(default)]
    pub branch_navigation: bool,
    #[serde(default)]
    pub message_rating: bool,
    #[serde(default)]
    pub tags: bool,
    #[serde(default)]
    pub bulk_selection: bool,
}

