pub enum UiInputType {
    /// One line of plain text. What a request without `UiRequest.inputType`
    /// asks for.
    #[serde(rename = "text")]
    Text,
    /// Masked text: the card must not echo it or keep it in history.
    #[serde(rename = "password")]
    Password,
    /// One of `UiRequest.options`, answered with its `value` in
    /// `UiResponse.text`.
    #[serde(rename = "select")]
    Select,
    /// A value this build does not know, from a newer daemon. It decodes
    /// only: it encodes as `"unknown"`, which the daemon refuses.
    #[serde(other, rename = "unknown")]
    Unknown,
}

/// One choice of a `UiInputType.select` prompt.
