/// An event the daemon pushed, decoded from its envelope by name.
///
/// An event without a payload is a unit variant: the window refetches what
/// it names. One this build does not know is `Event::Unknown`.
#[derive(Debug, Clone, PartialEq)]
pub enum Event {
    /// `turn.started`, scoped.
    TurnStarted(TurnStarted),
    /// `turn.delta`, scoped.
    TurnDelta(TurnDelta),
    /// The answer so far, parsed into blocks (`TurnBlocks`): files, status,
    /// text, reasoning, tool calls, code, error, sources, follow-ups. Parsing
    /// happens once, in the daemon; the UI only renders plain markdown.
    ///
    /// `turn.blocks`, scoped.
    TurnBlocks(TurnBlocks),
    /// `turn.completed`, scoped.
    TurnCompleted(TurnCompleted),
    /// `turn.failed`, scoped.
    TurnFailed(TurnFailed),
    /// An answer ended, in any chat (`TurnFinished`); unscoped, for
    /// notifications about chats no window shows.
    ///
    /// `turn.finished`.
    TurnFinished(TurnFinished),
    /// `chats.changed`.
    ChatsChanged(ChatsChanged),
    /// The saved accounts, or which one is active, changed: an account was
    /// added, switched to, signed in to or removed, from any window. Payload
    /// `AccountsChanged`.
    ///
    /// `accounts.changed`.
    AccountsChanged(AccountsChanged),
    /// `notes.changed`.
    NotesChanged(NotesChanged),
    /// `channels.message`, scoped.
    ChannelsMessage(ChannelMessagesChanged),
    /// Who is typing in a channel changed. Payload
    /// `ChannelTypingUsers`, scoped to `channel:<id>`.
    ///
    /// `channels.typing`, scoped.
    ChannelsTyping(ChannelTypingUsers),
    /// The channel list changed: a channel added, removed, renamed, or a new
    /// unread count. No payload.
    ///
    /// `channels.changed`.
    ChannelsChanged,
    /// `sync.status`.
    SyncStatus(SyncState),
    /// The realtime socket's health changed (connected, transport, latency,
    /// reconnects). No payload; `data.connection` says what it is now.
    ///
    /// Reserved; not published yet.
    ///
    /// `socket.health`.
    SocketHealth,
    /// Ask the shell to raise an OS notification.
    ///
    /// `notify.show`.
    NotifyShow(Notice),
    /// A chat ID was remapped after sync; the UI must rewrite its route
    /// without pushing a history entry.
    ///
    /// `route.remap`.
    RouteRemap(RouteRemap),
    /// The core needs an answer from the user: tool approval, an Open WebUI
    /// input prompt, an MCP approval, a Hermes decision. Answered with
    /// `ui.respond`.
    ///
    /// `ui.request`.
    UiRequest(UiRequest),
    /// A `ui.request` has been answered or has run out of time. Payload is
    /// `{requestId}`. Windows that did not answer close their card, so no
    /// window offers a choice that no longer counts.
    ///
    /// `ui.settled`.
    UiSettled(UiSettled),
    /// Emitted when `Capabilities` change — a server switch, a sign-in, the
    /// Apple helper becoming available.
    ///
    /// What the active account can use changed: another account, a server
    /// whose features or permissions changed, Hermes switched on or off. A
    /// window refetches `system.capabilities`.
    ///
    /// `capabilities.changed`.
    CapabilitiesChanged,
    /// The models on offer changed: a direct connection was added and its
    /// models discovered, or the server's list was refreshed. Also when the
    /// model the next turn runs with changed (a new Default Model, say). No
    /// payload; `models.list` says what they are.
    ///
    /// `models.changed`.
    ModelsChanged,
    /// The daemon needs a page opened in the system browser: an MCP
    /// server's OAuth sign-in. Payload `OpenUrl`. The first window to hear it
    /// opens it.
    ///
    /// `shell.openUrl`.
    OpenUrl(OpenUrl),
    /// A workspace section's items changed. Payload `WorkspaceChanged`.
    ///
    /// `workspace.changed`.
    WorkspaceChanged(WorkspaceChanged),
    /// Hermes's settings, sessions or jobs changed. No payload.
    ///
    /// `hermes.changed`.
    HermesChanged,
    /// The whisper models changed: a download moved, finished or failed, or
    /// one was deleted. Payload `VoiceModels`.
    ///
    /// `voice.changed`.
    VoiceChanged(VoiceModels),
    /// A model's tool asked to show a file from the chat's terminal. Payload
    /// `TerminalDisplayFile`, scoped to the chat.
    ///
    /// `terminal.displayFile`, scoped.
    TerminalDisplayFile(TerminalDisplayFile),
    /// Core's `AppSettings` changed, from any window or the daemon itself.
    /// No payload; `settings.get` says what they are now.
    ///
    /// `settings.changed`.
    SettingsChanged,
    /// A chat's queued messages changed. Payload `QueueState`, scoped to the
    /// chat.
    ///
    /// `queue.changed`, scoped.
    QueueChanged(QueueState),
    /// A merged response so far (Merge Responses). Payload `MergeProgress`,
    /// scoped to the chat.
    ///
    /// `messages.merge`, scoped.
    MessagesMerge(MergeProgress),
    /// The server suggests carrying on in a new chat with another model.
    /// Payload `HandoffRequest`; answered with `handoff.answer`.
    ///
    /// `handoff.requested`.
    HandoffRequested(HandoffRequest),
    /// A `handoff.requested` was answered or ran out of time. Payload
    /// `HandoffSettled`.
    ///
    /// `handoff.settled`.
    HandoffSettled(HandoffSettled),
    /// The Open WebUI prompt waiting in a chat came or went. Payload
    /// `ChatPromptState`, scoped to the chat.
    ///
    /// `chatPrompts.changed`, scoped.
    ChatPromptsChanged(ChatPromptState),
    /// An MCP App's host has something for its view: a message for the
    /// page, a new height, a start or an end. Payload `McpAppEvent`, scoped
    /// to the app's chat.
    ///
    /// `mcpApps.event`, scoped.
    McpAppsEvent(McpAppEvent),
    /// An event this build does not know, from a newer daemon, kept as it came.
    Unknown {
        name: String,
        payload: serde_json::Value,
    },
}

impl Event {
    /// Decodes `payload` as the event called `name`.
    ///
    /// A name this build does not know is `Event::Unknown`; a known one whose
    /// payload does not fit its DTO is an error. An event without a payload
    /// ignores whatever it carries.
    pub fn decode(name: &str, payload: serde_json::Value) -> serde_json::Result<Self> {
        Ok(match name {
            events::TURN_STARTED => Self::TurnStarted(serde_json::from_value(payload)?),
            events::TURN_DELTA => Self::TurnDelta(serde_json::from_value(payload)?),
            events::TURN_BLOCKS => Self::TurnBlocks(serde_json::from_value(payload)?),
            events::TURN_COMPLETED => Self::TurnCompleted(serde_json::from_value(payload)?),
            events::TURN_FAILED => Self::TurnFailed(serde_json::from_value(payload)?),
            events::TURN_FINISHED => Self::TurnFinished(serde_json::from_value(payload)?),
            events::CHATS_CHANGED => Self::ChatsChanged(serde_json::from_value(payload)?),
            events::ACCOUNTS_CHANGED => Self::AccountsChanged(serde_json::from_value(payload)?),
            events::NOTES_CHANGED => Self::NotesChanged(serde_json::from_value(payload)?),
            events::CHANNELS_MESSAGE => Self::ChannelsMessage(serde_json::from_value(payload)?),
            events::CHANNELS_TYPING => Self::ChannelsTyping(serde_json::from_value(payload)?),
            events::CHANNELS_CHANGED => Self::ChannelsChanged,
            events::SYNC_STATUS => Self::SyncStatus(serde_json::from_value(payload)?),
            events::SOCKET_HEALTH => Self::SocketHealth,
            events::NOTIFY_SHOW => Self::NotifyShow(serde_json::from_value(payload)?),
            events::ROUTE_REMAP => Self::RouteRemap(serde_json::from_value(payload)?),
            events::UI_REQUEST => Self::UiRequest(serde_json::from_value(payload)?),
            events::UI_SETTLED => Self::UiSettled(serde_json::from_value(payload)?),
            events::CAPABILITIES_CHANGED => Self::CapabilitiesChanged,
            events::MODELS_CHANGED => Self::ModelsChanged,
            events::OPEN_URL => Self::OpenUrl(serde_json::from_value(payload)?),
            events::WORKSPACE_CHANGED => Self::WorkspaceChanged(serde_json::from_value(payload)?),
            events::HERMES_CHANGED => Self::HermesChanged,
            events::VOICE_CHANGED => Self::VoiceChanged(serde_json::from_value(payload)?),
            events::TERMINAL_DISPLAY_FILE => {
                Self::TerminalDisplayFile(serde_json::from_value(payload)?)
            }
            events::SETTINGS_CHANGED => Self::SettingsChanged,
            events::QUEUE_CHANGED => Self::QueueChanged(serde_json::from_value(payload)?),
            events::MESSAGES_MERGE => Self::MessagesMerge(serde_json::from_value(payload)?),
            events::HANDOFF_REQUESTED => Self::HandoffRequested(serde_json::from_value(payload)?),
            events::HANDOFF_SETTLED => Self::HandoffSettled(serde_json::from_value(payload)?),
            events::CHAT_PROMPTS_CHANGED => {
                Self::ChatPromptsChanged(serde_json::from_value(payload)?)
            }
            events::MCP_APPS_EVENT => Self::McpAppsEvent(serde_json::from_value(payload)?),
            _ => Self::Unknown {
                name: name.to_owned(),
                payload,
            },
        })
    }

    /// The event's name, as the envelope carries it.
    pub fn name(&self) -> &str {
        match self {
            Self::TurnStarted(_) => events::TURN_STARTED,
            Self::TurnDelta(_) => events::TURN_DELTA,
            Self::TurnBlocks(_) => events::TURN_BLOCKS,
            Self::TurnCompleted(_) => events::TURN_COMPLETED,
            Self::TurnFailed(_) => events::TURN_FAILED,
            Self::TurnFinished(_) => events::TURN_FINISHED,
            Self::ChatsChanged(_) => events::CHATS_CHANGED,
            Self::AccountsChanged(_) => events::ACCOUNTS_CHANGED,
            Self::NotesChanged(_) => events::NOTES_CHANGED,
            Self::ChannelsMessage(_) => events::CHANNELS_MESSAGE,
            Self::ChannelsTyping(_) => events::CHANNELS_TYPING,
            Self::ChannelsChanged => events::CHANNELS_CHANGED,
            Self::SyncStatus(_) => events::SYNC_STATUS,
            Self::SocketHealth => events::SOCKET_HEALTH,
            Self::NotifyShow(_) => events::NOTIFY_SHOW,
            Self::RouteRemap(_) => events::ROUTE_REMAP,
            Self::UiRequest(_) => events::UI_REQUEST,
            Self::UiSettled(_) => events::UI_SETTLED,
            Self::CapabilitiesChanged => events::CAPABILITIES_CHANGED,
            Self::ModelsChanged => events::MODELS_CHANGED,
            Self::OpenUrl(_) => events::OPEN_URL,
            Self::WorkspaceChanged(_) => events::WORKSPACE_CHANGED,
            Self::HermesChanged => events::HERMES_CHANGED,
            Self::VoiceChanged(_) => events::VOICE_CHANGED,
            Self::TerminalDisplayFile(_) => events::TERMINAL_DISPLAY_FILE,
            Self::SettingsChanged => events::SETTINGS_CHANGED,
            Self::QueueChanged(_) => events::QUEUE_CHANGED,
            Self::MessagesMerge(_) => events::MESSAGES_MERGE,
            Self::HandoffRequested(_) => events::HANDOFF_REQUESTED,
            Self::HandoffSettled(_) => events::HANDOFF_SETTLED,
            Self::ChatPromptsChanged(_) => events::CHAT_PROMPTS_CHANGED,
            Self::McpAppsEvent(_) => events::MCP_APPS_EVENT,
            Self::Unknown { name, .. } => name,
        }
    }

    /// The payload as JSON: `{}` for an event without one.
    pub fn payload(&self) -> serde_json::Result<serde_json::Value> {
        match self {
            Self::TurnStarted(payload) => serde_json::to_value(payload),
            Self::TurnDelta(payload) => serde_json::to_value(payload),
            Self::TurnBlocks(payload) => serde_json::to_value(payload),
            Self::TurnCompleted(payload) => serde_json::to_value(payload),
            Self::TurnFailed(payload) => serde_json::to_value(payload),
            Self::TurnFinished(payload) => serde_json::to_value(payload),
            Self::ChatsChanged(payload) => serde_json::to_value(payload),
            Self::AccountsChanged(payload) => serde_json::to_value(payload),
            Self::NotesChanged(payload) => serde_json::to_value(payload),
            Self::ChannelsMessage(payload) => serde_json::to_value(payload),
            Self::ChannelsTyping(payload) => serde_json::to_value(payload),
            Self::SyncStatus(payload) => serde_json::to_value(payload),
            Self::NotifyShow(payload) => serde_json::to_value(payload),
            Self::RouteRemap(payload) => serde_json::to_value(payload),
            Self::UiRequest(payload) => serde_json::to_value(payload),
            Self::UiSettled(payload) => serde_json::to_value(payload),
            Self::OpenUrl(payload) => serde_json::to_value(payload),
            Self::WorkspaceChanged(payload) => serde_json::to_value(payload),
            Self::VoiceChanged(payload) => serde_json::to_value(payload),
            Self::TerminalDisplayFile(payload) => serde_json::to_value(payload),
            Self::QueueChanged(payload) => serde_json::to_value(payload),
            Self::MessagesMerge(payload) => serde_json::to_value(payload),
            Self::HandoffRequested(payload) => serde_json::to_value(payload),
            Self::HandoffSettled(payload) => serde_json::to_value(payload),
            Self::ChatPromptsChanged(payload) => serde_json::to_value(payload),
            Self::McpAppsEvent(payload) => serde_json::to_value(payload),
            Self::ChannelsChanged
            | Self::SocketHealth
            | Self::CapabilitiesChanged
            | Self::ModelsChanged
            | Self::HermesChanged
            | Self::SettingsChanged => Ok(serde_json::Value::Object(serde_json::Map::new())),
            Self::Unknown { payload, .. } => Ok(payload.clone()),
        }
    }

    /// Whether the event is published with a scope (`false` for an unknown one).
    pub fn is_scoped(&self) -> bool {
        let name = self.name();
        EVENTS.iter().any(|spec| spec.name == name && spec.scoped)
    }
}

